using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
namespace MochiDesktop {
 public static class GoogleNativeIntegrationTests {
  static void Assert(bool condition,string message){if(!condition)throw new Exception(message);}
  public static void Add(Action<string,Action> test,string directory){var now=DateTime.UtcNow;var config=new NativeGoogleConfig();
   test("Google calendar snapshot creates durable generic local reminders",delegate{var state=new StoredState();var batch=new NativeGoogleBatch{CalendarSnapshotAvailable=true,HorizonEndUtcTicks=now.AddDays(30).Ticks};batch.CalendarEvents.Add(new NativeCalendarEvent{Key="private-calendar:event1",StartUtcTicks=now.AddHours(2).Ticks,EndUtcTicks=now.AddHours(3).Ticks});var result=GoogleNativeIntegration.Apply(state,batch,config,now);var r=state.Reminders.Single();Assert(result.Changed&&r.GoogleService=="calendar"&&r.DueUtcTicks==now.AddHours(2).AddMinutes(-10).Ticks&&r.Title=="Google Calendar event"&&!r.OpenUrlOnDue&&!r.Id.Contains("private"),"Calendar reminder leaked metadata or wrong schedule");var store=new StateStore(Path.Combine(directory,"google-calendar-host"));store.Save(state);Assert(store.Load().Reminders[0].Id==r.Id,"Snapshot did not persist");});
   test("Repeated calendar snapshot preserves delivery claims and pause",delegate{var state=new StoredState();var batch=new NativeGoogleBatch{CalendarSnapshotAvailable=true};batch.CalendarEvents.Add(new NativeCalendarEvent{Key="event",StartUtcTicks=now.Ticks,EndUtcTicks=now.AddHours(1).Ticks});GoogleNativeIntegration.Apply(state,batch,config,now);var r=state.Reminders[0];ReminderEngine.ClaimDue(state,now);r.Paused=true;var result=GoogleNativeIntegration.Apply(state,batch,config,now);Assert(!result.Changed&&r.Completed&&r.Paused&&ReminderEngine.ClaimDue(state,now).Count==0,"Snapshot reset a claimed occurrence");});
   test("Moved calendar event updates its own local schedule once",delegate{var state=new StoredState();var item=new NativeCalendarEvent{Key="event",StartUtcTicks=now.AddHours(1).Ticks,EndUtcTicks=now.AddHours(2).Ticks};var batch=new NativeGoogleBatch{CalendarSnapshotAvailable=true};batch.CalendarEvents.Add(item);GoogleNativeIntegration.Apply(state,batch,config,now);string id=state.Reminders[0].Id;item.StartUtcTicks=now.AddHours(3).Ticks;item.EndUtcTicks=now.AddHours(4).Ticks;GoogleNativeIntegration.Apply(state,batch,config,now);Assert(state.Reminders.Count==1&&state.Reminders[0].Id==id&&state.Reminders[0].DueUtcTicks==now.AddHours(3).AddMinutes(-10).Ticks,"Moved event duplicated");});
   test("Failed calendar refresh never erases cached native schedules",delegate{var state=new StoredState();var r=ReminderEngine.Create("Cached",now.AddHours(1),"none");r.GoogleService="calendar";state.Reminders.Add(r);GoogleNativeIntegration.Apply(state,new NativeGoogleBatch{CalendarSnapshotAvailable=false},config,now);Assert(state.Reminders.Count==1,"Failed refresh erased cache");});
   test("Cancelled calendar events prune only Google schedules",delegate{var state=new StoredState();state.Reminders.Add(ReminderEngine.Create("Own reminder",now.AddHours(1),"none"));var r=ReminderEngine.Create("Cancelled",now.AddHours(2),"none");r.GoogleService="calendar";state.Reminders.Add(r);GoogleNativeIntegration.Apply(state,new NativeGoogleBatch{CalendarSnapshotAvailable=true},config,now);Assert(state.Reminders.Count==1&&state.Reminders[0].Title=="Own reminder","Cancellation pruned own reminder");});
   test("All-day reminders use configured local hour without timed offset",delegate{DateTime day=TimeZoneInfo.ConvertTimeFromUtc(now,TimeZoneInfo.Local).Date.AddDays(1);var item=new NativeCalendarEvent{AllDay=true,StartUtcTicks=ReminderEngine.LocalToUtc(day,TimeZoneInfo.Local).Ticks};Assert(GoogleNativeIntegration.CalendarDue(item,new NativeGoogleConfig{OffsetMinutes=60,AllDayHour=9})==ReminderEngine.LocalToUtc(day.AddHours(9),TimeZoneInfo.Local).Ticks,"All-day reminder used event offset");});
   test("Google mail outbox maps to generic notify-only reminder and acknowledgement",delegate{var state=new StoredState();var batch=new NativeGoogleBatch();batch.MailAlerts.Add(new NativeMailAlert{Key="opaque-message",ReceivedUtcTicks=now.Ticks,Important=true});var result=GoogleNativeIntegration.Apply(state,batch,config,now);Assert(result.AcknowledgeMailKeys.SequenceEqual(new[]{"opaque-message"})&&state.Reminders.Single().Title=="Important Gmail message"&&!state.Reminders[0].OpenUrlOnDue&&state.Reminders[0].ActionUrl=="https://mail.google.com/","Mail alert missing or automatically opened");});
   test("Mail outbox replay after restart cannot duplicate notification",delegate{var state=new StoredState();var batch=new NativeGoogleBatch();batch.MailAlerts.Add(new NativeMailAlert{Key="same"});GoogleNativeIntegration.Apply(state,batch,config,now);ReminderEngine.ClaimDue(state,now);state.Reminders.Clear();var store=new StateStore(Path.Combine(directory,"google-mail-host"));store.Save(state);var loaded=store.Load();var result=GoogleNativeIntegration.Apply(loaded,batch,config,now);Assert(loaded.Reminders.Count==0&&result.AcknowledgeMailKeys.Count==1,"Replay recreated a delivered mail notification");});
   test("Muted Gmail outbox remains unacknowledged for later",delegate{var state=new StoredState();var batch=new NativeGoogleBatch();batch.MailAlerts.Add(new NativeMailAlert{Key="mail"});var result=GoogleNativeIntegration.Apply(state,batch,new NativeGoogleConfig{GmailMuted=true},now);Assert(state.Reminders.Count==0&&result.AcknowledgeMailKeys.Count==0,"Muted mail was discarded");});
   test("Full native reminder capacity never acknowledges an unqueued email",delegate{var state=new StoredState();for(int i=0;i<1000;i++)state.Reminders.Add(ReminderEngine.Create("Own "+i,now.AddDays(1),"none"));var batch=new NativeGoogleBatch();batch.MailAlerts.Add(new NativeMailAlert{Key="waiting"});var result=GoogleNativeIntegration.Apply(state,batch,config,now);Assert(state.Reminders.Count==1000&&result.AcknowledgeMailKeys.Count==0&&!string.IsNullOrEmpty(result.Warning),"Capacity lost a mail alert");});
   test("Explicit Google disconnect removes only service-generated local data",delegate{var state=new StoredState();Reminder own=ReminderEngine.Create("Own",now,"none"),cal=ReminderEngine.Create("Calendar",now,"none"),mail=ReminderEngine.Create("Mail",now,"none");cal.GoogleService="calendar";mail.GoogleService="gmail";state.Reminders.AddRange(new[]{own,cal,mail});ReminderQueue.Enqueue(state,new[]{cal});Assert(GoogleNativeIntegration.RemoveService(state,"calendar")&&state.Reminders.Count==2&&state.PendingAlerts.Count==0&&state.Reminders.Contains(own)&&state.Reminders.Contains(mail),"Disconnect touched other reminders");});
  }
 }
}
